[ExtensionOf(classstr(CustVendPaymReconciliationSetStatus))]
internal final class METCustVendPaymReconciliationSetStatus_Extension
{
}

Method.Source:
    /// <summary>
    /// Validates the current payment.
    /// </summary>
    /// <param name = "_ledgerJournalTrans">The <c>LedgerJournalTrans</c> record to be validated.</param>
    /// <returns>true if a valid payment; otherwise, false.</returns>
    protected boolean validatePayment(LedgerJournalTrans _ledgerJournalTrans)
    {
        boolean     metRet = next validatePayment(_ledgerJournalTrans);

        if (_ledgerJournalTrans.metValidatePaymentStatus())
        {
            metRet = METPaymentControl::newFromledgerJournalTrans(_ledgerJournalTrans, METRecordAction::Update, this.parmStatus()).validateAction();
        }

        return metRet;
    }
